var ids=['projects','projects--empty','project','recent','artifacts','artifacts--empty','artifacts--detail','routines','routines--new','customize','customize--profile'];
var d=sketch.getDocuments().find(function(d){return String(d.id)==='40E7AE0D-B568-476B-9630-D3AB62280DBE';});
d.pages.filter(function(p){return p.name==='Proto macOS Light'||p.name==='Proto macOS Dark';}).forEach(function(p){p.layers.filter(function(s){return s.name.indexOf('Screen/macos/')===0&&ids.indexOf(s.name.split('/').pop())>=0;}).forEach(function(s){var id=s.name.split('/').pop();var sb=s.layers.find(function(l){return l.name==='sidebar';});var list=sb.layers.find(function(l){return l.name==='list';});list.layers.forEach(function(r){if(r.name==='link:projects'){var label=r.layers.find(function(l){return l.name==='label';});if(label){label.frame.width=164;label.fixedWidth=true;r.stackLayout.apply();}}if(r.name==='link:conversation'){var t=r.layers.find(function(l){return l.type==='Text'&&l.name.indexOf('sf:')!==0;});if(t){var v=t.text;t.text=v.indexOf('billing')>=0?'Move the billing webhook…':v.indexOf('Q3')>=0?'Draft the Q3 investor update':'Why is the Mac build larger?';t.frame.width=180;}}});if(id==='projects--empty'){list.layers.slice().forEach(function(r){if(r.name==='link:project'||r.name==='link:conversation'||(r.name.indexOf('section')===0&&r.layers.some(function(l){return l.text==='Recent';})))r.remove();});var toolbar=s.layers.find(function(l){return l.name==='content-col';}).layers.find(function(l){return l.name==='toolbar';});toolbar.layers.slice().forEach(function(l){if(l.name==='link:project')l.remove();});toolbar.stackLayout.apply();}list.stackLayout.apply();var found=[];function walk(l){if(l.name.indexOf('link:')===0)l.name=l.name.replace(/ \d+$/,'');if(l.name==='inspector'||l.name.indexOf('sheet/')===0)found.push({name:l.name,x:l.frame.x,y:l.frame.y,w:l.frame.width,h:l.frame.height});(l.layers||[]).forEach(walk);}walk(s);console.log(JSON.stringify({id:id,frame:String(s.id),name:s.name,w:s.frame.width,h:s.frame.height,x:s.frame.x,y:s.frame.y,panels:found}));});});